  function fillColorsAndPrice(p){
    const aliases={fuchsia:'Pink',magenta:'Pink',blush:'Pink',navy:'Blue',teal:'Blue',mustard:'Yellow',burgundy:'Red',maroon:'Red',ivory:'Cream',beige:'Tan',grey:'Gray'};
    const canonical=value=>C.colors.find(c=>c.toLowerCase()===String(value||'').trim().toLowerCase())||aliases[String(value||'').trim().toLowerCase()];
    for(const key of ['color','color2'])if(p[key]&&canonical(p[key]))p[key]=canonical(p[key]);
    const text=(p.title+'\n'+p.description).toLowerCase();
    const names=[...C.colors.map(c=>c.toLowerCase()),...Object.keys(aliases)];
    const found=[...text.matchAll(new RegExp('\\b('+names.join('|')+')\\b','g'))].map(m=>canonical(m[0]));
    const distinct=[...new Set(found)];
    if(!p.color)p.color=distinct[0]||'';
    if(!p.color2)p.color2=distinct.find(c=>c!==p.color)||'';
    if(!p.price){const match=(p.description||'').match(/(?:^|\n)\s*(?:listing|asking|sale) price\s*:\s*\$?([0-9]+(?:\.[0-9]{1,2})?)\s*(?:USD)?\s*(?:$|\n)/i);if(match&&Number(match[1])>0)p.price=match[1];}
  }
  function fillDetails(p){
    fillBrand(p);fillColorsAndPrice(p);
    const text=(p.title+'\n'+p.description).replace(/\*+/g,'');
    const put=(key,value)=>{
      if(String(p[key]||'').trim()||!value||/^(unknown|n\/a|not known)$/i.test(value))return;
      const allowed=key==='department'?Object.keys(C.taxonomy.departments):key==='category'?(C.taxonomy.departments[p.department]||[]):key==='size'?(C.taxonomy.sizes[p.category]||[]):key==='color'||key==='color2'?C.colors.filter(c=>key!=='color2'||c!==p.color):null;
      if(allowed){const match=allowed.find(option=>option.toLowerCase()===value.trim().toLowerCase());if(match)p[key]=match;}
      else p[key]=value.trim();
    };
    for(const key of ['brand','department','category','size']){
      const re=new RegExp('^\\s*(?:[-•]\\s*)?(?:'+(key==='size'?'(?:tag )?size':key)+')\\s*:\\s*([^\\n]+)','im');
      put(key,text.match(re)?.[1]);
    }
    if(!p.department){if(/\bwomen(?:'s|’s)?\b|\bladies\b/i.test(text))put('department','Women');else if(/\bmen(?:'s|’s)?\b/i.test(text))put('department','Men');}
    if(!p.department&&!/\b(kids?|girls?|boys?|baby|toddler|mens?|men’s|men's)\b/i.test(text)){
      if(/^(?:Linda Allard )?Ellen Tracy$|^Bardot$/i.test(p.brand?.trim()||'')||/\b(?:maxi|midi|cocktail|evening|wedding)\s+(?:lace\s+)?(?:dress|gown)\b/i.test(text))put('department','Women');
    }
    if(!p.size)put('size',text.match(/\bsize\s+(XXS|XS|XXL|XL|S|M|L|\d+(?:\.\d+)?)(?=\s|[,.;]|$)/i)?.[1]?.toUpperCase());
    if(!p.category&&p.department){
      const aliases={Dresses:/\bdress(?:es)?\b/i,Shorts:/\bshorts\b/i,Skirts:/\bskirts?\b/i,Jeans:/\bjeans\b/i,Sweaters:/\bsweaters?\b/i};
      const matches=Object.entries(aliases).filter(([k,re])=>C.taxonomy.departments[p.department]?.includes(k)&&re.test(text));
      if(matches.length===1)put('category',matches[0][0]);
    }
    put('size',text.match(/(?:tag )?size\s*:\s*([^\n]+)/i)?.[1]||text.match(/\bsize\s+(XXS|XS|XXL|XL|S|M|L|\d+(?:\.\d+)?)(?=\s|[,.;]|$)/i)?.[1]);
  }
  function updateCardTaxonomy(card,p){
    for(const key of ['department','category','size','color','color2']){
      const current=card.querySelector('[data-field="'+key+'"]');if(!current)continue;
      const options=key==='department'?Object.keys(C.taxonomy.departments):key==='category'?(C.taxonomy.departments[p.department]||[]):key==='color'||key==='color2'?C.colors.filter(c=>key!=='color2'||c!==p.color):(C.taxonomy.sizes[p.category]||[]);
      const select=document.createElement('select');select.dataset.field=key;select.setAttribute('aria-label',key+' for SKU '+p.sku);
      const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=key==='category'&&!p.department?'Choose department first':key==='size'&&!p.category?'Choose category first':'Choose '+(key==='color2'?'second color':key);select.append(placeholder);
      for(const value of options){const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)}
      select.value=options.includes(String(p[key]))?p[key]:'';select.style.background=select.value?'':'#fff0cf';current.replaceWith(select);
    }
  }
